(() => {
    const MINUTE_MS = 60000;
    const status = document.getElementById("status");
    let ready = false;
    function renderClock() {
        const now = new Date();
        const clock = document.getElementById("clock");
        const date = document.getElementById("date");
        if (clock) clock.textContent = now.toLocaleTimeString([], {hour:"2-digit", minute:"2-digit"});
        if (date) date.textContent = now.toLocaleDateString([], {weekday:"long", month:"long", day:"numeric"});
    }
    renderClock();
    setInterval(() => { if (!document.hidden) renderClock(); }, MINUTE_MS);
    document.addEventListener("visibilitychange", renderClock);
    window.addEventListener("dikciz-ready", () => { ready = true; });
    document.getElementById("search")?.addEventListener("submit", async event => {
        event.preventDefault();
        const query = document.getElementById("query").value.trim();
        if (!query || !ready) return;
        try {
            const result = await dikciz.command("intent", {
                intentType:"activity", action:"android.intent.action.VIEW",
                data:"https://www.google.com/search?q=" + encodeURIComponent(query)
            });
            const launch = result.activityLaunches?.[0];
            status.textContent = launch?.verified ? "Browser opened." : "Browser requested. " + (launch?.reason || "Check Android for the result.");
        } catch (error) { status.textContent = "Search unavailable: " + error.message; }
    });
})();

(() => {
    const MAX_VISIBLE = 6;
    const status = document.getElementById("status");
    const list = document.getElementById("apps");
    let apps = [];
    let launching = false;
    function render() {
        if (!list) return;
        list.replaceChildren();
        const query = document.getElementById("app-query")?.value.trim().toLocaleLowerCase() || "";
        const matches = apps.filter(app => (app.label + " " + app.packageName).toLocaleLowerCase().includes(query));
        matches.slice(0, MAX_VISIBLE).forEach(app => {
            const button = document.createElement("button");
            button.type = "button";
            button.className = "secondary";
            button.textContent = app.label;
            button.addEventListener("click", async () => {
                if (launching) return;
                launching = true;
                button.disabled = true;
                status.textContent = "Opening " + app.label + "...";
                try {
                    const result = await dikciz.command("appAction", {action:"launch", component:app.component});
                    const launch = result.activityLaunches?.[0];
                    status.textContent = launch?.verified ? app.label + " opened." : "Launch unverified: " + (launch?.reason || result.outcome || "Check Android.");
                } catch (error) { status.textContent = "Could not open app: " + error.message; }
                finally { launching = false; button.disabled = false; }
            });
            list.append(button);
        });
        status.textContent = matches.length ? "Showing " + Math.min(matches.length, MAX_VISIBLE) + " of " + matches.length + ". Use the drawer to add shortcuts." : "No matching installed apps.";
    }
    document.getElementById("app-query")?.addEventListener("input", render);
    window.addEventListener("dikciz-ready", async () => {
        try {
            const result = await dikciz.command("appCatalogue");
            apps = Array.isArray(result.apps) ? result.apps : [];
            render();
        } catch (error) { status.textContent = "Apps unavailable: " + error.message; }
    });
})();

(() => {
    const MAX_NOTE_LENGTH = 2000;
    const note = document.getElementById("note");
    const button = document.getElementById("save");
    const status = document.getElementById("status");
    let dirty = false;
    function render(state) {
        if (note && !dirty) note.value = typeof state.text === "string" ? state.text.slice(0, MAX_NOTE_LENGTH) : "";
    }
    note?.addEventListener("input", () => { dirty = true; status.textContent = "Unsaved changes. Tap Save note."; });
    window.addEventListener("dikciz-ready", () => render(selfWidget.state));
    window.addEventListener("dikciz-state", event => render(event.detail || {}));
    button?.addEventListener("click", async () => {
        const text = note.value.slice(0, MAX_NOTE_LENGTH);
        button.disabled = true;
        try {
            await selfWidget.patchState({text});
            dirty = note.value !== text;
            status.textContent = dirty ? "New changes are not saved yet." : "Note saved on this phone.";
        } catch (error) { status.textContent = "Note not saved: " + error.message; }
        finally { button.disabled = false; }
    });
})();

(() => {
    const REQUEST_TIMEOUT_MS = 15000;
    const MAX_RESPONSE_BYTES = 65536;
    const CITY_LIMIT = 5;
    const status = document.getElementById("status");
    const choices = document.getElementById("choices");
    const refreshButton = document.getElementById("refresh");
    const findButton = document.getElementById("find");
    let state = {};
    let busy = false;
    const text = (id, value) => { const node = document.getElementById(id); if (node) node.textContent = value; };
    const number = (value, suffix) => Number.isFinite(value) ? Math.round(value) + suffix : "Unavailable";
    const validCity = city => city && typeof city.name === "string" && city.name.length <= 120 && Number.isFinite(city.latitude) && Math.abs(city.latitude) <= 90 && Number.isFinite(city.longitude) && Math.abs(city.longitude) <= 180;
    function setBusy(value) {
        busy = value;
        findButton.disabled = value;
        refreshButton.disabled = value || !validCity(state.city);
        choices?.querySelectorAll("button").forEach(button => { button.disabled = value; });
    }
    async function request(url) {
        const controller = new AbortController();
        const timeout = setTimeout(() => controller.abort(), REQUEST_TIMEOUT_MS);
        try {
            const response = await fetch(url, {signal:controller.signal, credentials:"omit", referrerPolicy:"no-referrer"});
            if (!response.ok) throw new Error("Service returned HTTP " + response.status);
            const reader = response.body.getReader();
            const chunks = [];
            let length = 0;
            while (true) {
                const chunk = await reader.read();
                if (chunk.done) break;
                length += chunk.value.byteLength;
                if (length > MAX_RESPONSE_BYTES) {
                    await reader.cancel();
                    throw new Error("Service response is too large.");
                }
                chunks.push(chunk.value);
            }
            const bytes = new Uint8Array(length);
            let offset = 0;
            for (const chunk of chunks) { bytes.set(chunk, offset); offset += chunk.byteLength; }
            const result = JSON.parse(new TextDecoder().decode(bytes));
            if (!result || typeof result !== "object" || Array.isArray(result) || result.error) throw new Error("Invalid service response.");
            return result;
        } finally { clearTimeout(timeout); }
    }
    function render() {
        text("place", validCity(state.city) ? state.city.name : "Choose your city");
        const weather = state.weather || {};
        text("temperature", number(weather.temperature, "°C"));
        text("feels", number(weather.feels, "°C"));
        text("wind", number(weather.wind, ""));
        text("rain", number(weather.rain, "%"));
        text("range", Number.isFinite(weather.low) && Number.isFinite(weather.high) ? Math.round(weather.low) + " / " + Math.round(weather.high) + "°" : "Unavailable");
        text("aqi", number(state.air?.aqi, ""));
        text("weather-status", weather.fetchedAt ? "Saved weather, fetched " + new Date(weather.fetchedAt).toLocaleString() + ". Refresh for current data." : "Weather has not been loaded.");
        text("air-status", state.air?.fetchedAt ? "Saved air data, fetched " + new Date(state.air.fetchedAt).toLocaleString() + ". Lower AQI means cleaner air." : "Air quality has not been loaded.");
        setBusy(busy);
    }
    async function refresh() {
        if (busy || !validCity(state.city)) return;
        setBusy(true);
        status.textContent = "Fetching weather and air quality...";
        const location = "latitude=" + encodeURIComponent(state.city.latitude) + "&longitude=" + encodeURIComponent(state.city.longitude);
        try {
            const results = await Promise.allSettled([
                request("https://api.open-meteo.com/v1/forecast?" + location + "&current=temperature_2m,apparent_temperature,wind_speed_10m&daily=temperature_2m_max,temperature_2m_min,precipitation_probability_max&forecast_days=1&timezone=auto"),
                request("https://air-quality-api.open-meteo.com/v1/air-quality?" + location + "&current=european_aqi&forecast_days=1")
            ]);
            const errors = [];
            if (results[0].status === "fulfilled" && Number.isFinite(results[0].value.current?.temperature_2m)) {
                const data = results[0].value;
                state.weather = {temperature:data.current.temperature_2m, feels:data.current.apparent_temperature, wind:data.current.wind_speed_10m, high:data.daily?.temperature_2m_max?.[0], low:data.daily?.temperature_2m_min?.[0], rain:data.daily?.precipitation_probability_max?.[0], fetchedAt:Date.now()};
            } else { errors.push("Weather unavailable"); }
            if (results[1].status === "fulfilled" && Number.isFinite(results[1].value.current?.european_aqi)) {
                state.air = {aqi:results[1].value.current.european_aqi, fetchedAt:Date.now()};
            } else { errors.push("Air quality unavailable"); }
            await selfWidget.patchState({city:state.city, weather:state.weather || {}, air:state.air || {}});
            render();
            status.textContent = errors.length ? errors.join(". ") + ". Saved readings are shown when available. Try Refresh weather." : "Saved latest readings. Refresh when needed.";
        } catch (error) { status.textContent = "Could not save readings: " + error.message; }
        finally { setBusy(false); }
    }
    document.getElementById("city-search")?.addEventListener("submit", async event => {
        event.preventDefault();
        if (busy) return;
        const query = document.getElementById("city").value.trim();
        if (query.length < 2) { status.textContent = "Enter at least two characters."; return; }
        setBusy(true);
        choices.replaceChildren();
        status.textContent = "Searching cities...";
        try {
            const data = await request("https://geocoding-api.open-meteo.com/v1/search?name=" + encodeURIComponent(query) + "&count=" + CITY_LIMIT + "&language=en&format=json");
            const cities = Array.isArray(data.results) ? data.results.slice(0, CITY_LIMIT) : [];
            for (const result of cities) {
                const city = {name:[result.name, result.admin1, result.country].filter(value => typeof value === "string").join(", ").slice(0,120), latitude:result.latitude, longitude:result.longitude};
                if (!validCity(city)) continue;
                const button = document.createElement("button");
                button.type = "button";
                button.className = "secondary";
                button.textContent = city.name;
                button.addEventListener("click", async () => {
                    if (busy) return;
                    setBusy(true);
                    try {
                        await selfWidget.patchState({city, weather:{}, air:{}});
                        state = {city};
                        choices.replaceChildren();
                        render();
                    } catch (error) {
                        status.textContent = "Could not save city: " + error.message;
                        setBusy(false);
                        return;
                    }
                    setBusy(false);
                    await refresh();
                });
                choices.append(button);
            }
            status.textContent = choices.children.length ? "Choose the matching city." : "No matching cities. Try another name.";
        } catch (error) { status.textContent = "City search unavailable. Check your connection and retry."; }
        finally { setBusy(false); }
    });
    refreshButton?.addEventListener("click", refresh);
    window.addEventListener("dikciz-ready", () => {
        state = selfWidget.state || {};
        render();
        if (validCity(state.city)) status.textContent = "Saved city and readings. Tap Refresh weather to update.";
    });
    window.addEventListener("dikciz-state", event => {
        state = event.detail || {};
        render();
    });
})();

(() => {
    const status = document.getElementById("status");
    const button = document.getElementById("refresh");
    async function refresh() {
        button.disabled = true;
        try {
            const state = await dikciz.command("deviceState");
            const known = Number.isFinite(state.batteryLevel) && state.batteryLevel >= 0 && Number.isFinite(state.batteryScale) && state.batteryScale > 0;
            const battery = document.getElementById("battery");
            const power = document.getElementById("power");
            const network = document.getElementById("network");
            const connection = document.getElementById("connection");
            if (battery) battery.textContent = known ? Math.round(state.batteryLevel * 100 / state.batteryScale) + "%" : "Unknown";
            if (power) power.textContent = state.chargingSource > 0 ? "Plugged in" : "On battery";
            if (network) network.textContent = state.vpn ? "VPN" : state.wifi ? "Wi-Fi" : state.cellular ? "Mobile" : state.networkAvailable ? "Network" : "Offline";
            if (connection) connection.textContent = state.internetValidated ? "Android confirms internet" : "Internet not confirmed";
            status.textContent = "Updated " + new Date().toLocaleTimeString([], {hour:"2-digit",minute:"2-digit"}) + (state.powerSaveMode ? ". Battery saver is on." : ". Battery saver is off.");
        } catch (error) { status.textContent = "Phone data unavailable: " + error.message; }
        finally { button.disabled = false; }
    }
    button?.addEventListener("click", refresh);
    window.addEventListener("dikciz-ready", refresh);
})();

