local LOW_LEVEL = 20
local RESET_LEVEL = 30
local CHARGING = 2
local FULL = 5
function on_event(event)
  local level = event.payload.level
  local status = event.payload.status
  if event.type ~= "battery" or type(level) ~= "number" or level < 0 or level > 100 then
    return { status = "Waiting for battery data" }
  end
  if level >= RESET_LEVEL or status == CHARGING or status == FULL then
    return { status = "Reminder reset", actions = { { type = "patchState", values = { alerted = false } } } }
  end
  if level > LOW_LEVEL or context.state.alerted then
    return { status = "No reminder needed" }
  end
  if not context.androidAccess.notificationPosting then
    return { status = "Allow Android notifications in Automation settings first" }
  end
  return { status = "Low battery reminder requested", actions = {
    { type = "patchState", values = { alerted = true } },
    { type = "postNotification", title = "Battery is low", text = tostring(level) .. "% remaining. Time to charge." }
  } }
end

local READY_LEVEL = 80
local RESET_LEVEL = 75
local CHARGING = 2
local FULL = 5
function on_event(event)
  local level = event.payload.level
  local status = event.payload.status
  if event.type ~= "battery" or type(level) ~= "number" or level < 0 or level > 100 then
    return { status = "Waiting for battery data" }
  end
  if level < RESET_LEVEL or (status ~= CHARGING and status ~= FULL) then
    return { status = "Reminder reset", actions = { { type = "patchState", values = { alerted = false } } } }
  end
  if level < READY_LEVEL or context.state.alerted then
    return { status = "No reminder needed" }
  end
  if not context.androidAccess.notificationPosting then
    return { status = "Allow Android notifications in Automation settings first" }
  end
  return { status = "Charging reminder requested", actions = {
    { type = "patchState", values = { alerted = true } },
    { type = "postNotification", title = "Charged enough", text = tostring(level) .. "% charged. You can unplug your phone." }
  } }
end

function on_event(event)
  if event.type ~= "manual" then return { status = "Run manually to lock the screen" } end
  if not context.androidAccess.deviceAdminActive then
    return { status = "Enable Device Administration in Automation settings first" }
  end
  return { status = "Lock requested", actions = { { type = "lockDevice" } } }
end
